void blk_queue_end_tag ( struct request_queue * q , struct request * rq ) { struct blk_queue_tag * bqt = q -> queue_tags ; unsigned tag = rq -> tag ; list_del_init ( & rq -> queuelist ) ; rq -> rq_flags &= ~ RQF_QUEUED ; rq -> tag = - 1 ; rq -> internal_tag = - 1 ; if ( unlikely ( bqt -> tag_index [ tag ] == NULL ) ) { printk ( KERN_ERR "%s: tag %d is missing\n" , __func__ , tag ) ; } bqt -> tag_index [ tag ] = NULL ; if ( unlikely ( ! test_bit ( tag , bqt -> tag_map ) ) ) { printk ( KERN_ERR "%s: attempt to clear non-busy tag (%d)\n" , __func__ , tag ) ; return ; } clear_bit_unlock ( tag , bqt -> tag_map ) ; } 